begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"authenticated","sub":"user_billingowner"}',true);
select public.onboard_business('Billing demo','healthcare','GH','Africa/Accra','Main','Test address');
create temp table billing_ids as select b.id business_id,l.id location_id from public.businesses b join public.locations l on l.business_id=b.id where b.owner_user_id='user_billingowner';
grant select on billing_ids to authenticated,service_role;
set local role authenticated;
select public.create_queue('b1000000-0000-4000-8000-000000000001',(select business_id from billing_ids),(select location_id from billing_ids),'One',null,300,3,false,false);
select public.create_queue('b1000000-0000-4000-8000-000000000002',(select business_id from billing_ids),(select location_id from billing_ids),'Two',null,300,3,false,false);
select public.create_queue('b1000000-0000-4000-8000-000000000003',(select business_id from billing_ids),(select location_id from billing_ids),'Three',null,300,3,false,false);
select throws_ok($$select public.create_queue('b1000000-0000-4000-8000-000000000004',(select business_id from billing_ids),(select location_id from billing_ids),'Four',null,300,3,false,false)$$,'QZ009',null,'free queue capacity enforced in database');
select lives_ok($$select public.create_queue('b1000000-0000-4000-8000-000000000003',(select business_id from billing_ids),(select location_id from billing_ids),'Retry',null,300,3,false,false)$$,'retry remains idempotent at capacity');
select ok(not has_function_privilege('authenticated','public.confirm_checkout(uuid,text,text,text,timestamptz,timestamptz)','EXECUTE'),'business browser cannot confirm its own payment');
select ok(not has_function_privilege('anon','public.sync_subscription_event(text,text,text,text,text,public.subscription_status,timestamptz,timestamptz)','EXECUTE'),'anonymous cannot change paid state');
reset role;
insert into public.billing_checkouts(reference,business_id,plan,provider_plan_code,amount,currency) values('b1000000-0000-4000-8000-000000000099',(select business_id from billing_ids),'STARTER','PLN_fixture',100000,'NGN');
set local role service_role;
select lives_ok($$select public.confirm_checkout('b1000000-0000-4000-8000-000000000099','charge:fixture','CUS_fixture','SUB_fixture',now(),now()+interval '1 month')$$,'verified server confirmation activates subscription');
select lives_ok($$select public.confirm_checkout('b1000000-0000-4000-8000-000000000099','charge:fixture','CUS_fixture','SUB_fixture',now(),now()+interval '1 month')$$,'duplicate webhook is idempotent');
select is((select count(*) from public.webhook_events where provider_event_id='charge:fixture'),1::bigint,'one webhook event retained');
select is((select subscription_tier::text from public.businesses where id=(select business_id from billing_ids)),'STARTER','verified tier available');
set local role authenticated;
select lives_ok($$select public.create_queue('b1000000-0000-4000-8000-000000000004',(select business_id from billing_ids),(select location_id from billing_ids),'Four',null,300,3,false,false)$$,'paid queue capacity allows new service');
set local role service_role;
select lives_ok($$select public.sync_subscription_event('disabled:fixture','subscription.disable','CUS_fixture','SUB_fixture','PLN_fixture','cancelled',now()+interval '1 second',now())$$,'cancellation sync succeeds');
select is((select subscription_tier::text from public.businesses where id=(select business_id from billing_ids)),'FREE','cancellation removes paid entitlement');
select lives_ok($$select public.sync_subscription_event('late:fixture','subscription.create','CUS_fixture','SUB_fixture','PLN_fixture','active',now()-interval '1 second',now()+interval '1 month')$$,'old event safely accepted without restoring paid state');
select is((select subscription_tier::text from public.businesses where id=(select business_id from billing_ids)),'FREE','out-of-order webhook cannot restore paid tier');
select is((select count(*) from public.queues where business_id=(select business_id from billing_ids)),4::bigint,'downgrade never deletes existing queues');
reset role;
set constraints all immediate;
select * from finish();rollback;
